<?php require __DIR__.'/bootstrap.php'; require __DIR__.'/layout.php'; $u=require_login(); $rows=[]; $term=trim($_GET['documento']??''); if($term!==''){ $q=$db->prepare('SELECT c.*,o.id operacion_id,o.cedente,o.cartera,o.numero_operacion,o.saldo,o.capital,o.moneda FROM clientes c LEFT JOIN operaciones o ON o.cliente_id=c.id WHERE c.numero_documento=?');$q->execute([$term]);$rows=$q->fetchAll(); } page_start('Buscar cliente',$u);?><section class="panel"><form method="get" class="inline"><label>DNI / Documento<input name="documento" value="<?=e($term)?>" required></label><button class="primary">Buscar</button></form></section><?php if($term!==''&&!$rows):?><div class="alert">No se encontraron resultados.</div><?php endif; foreach($rows as $r):?><article class="panel result"><div><h2><?=e($r['nombre_completo'])?></h2><p><?=e($r['tipo_documento'])?> <?=e($r['numero_documento'])?> · <?=e($r['cedente'])?> / <?=e($r['cartera'])?></p><strong><?=money($r['saldo'])?> <?=e($r['moneda'])?></strong></div><?php if($r['operacion_id']):?><a class="primary" href="<?=url('nuevo-acuerdo.php?operacion='.(int)$r['operacion_id'])?>">Generar acuerdo</a><?php endif?></article><?php endforeach; page_end();

